double g_price{ 0.0 };

void applyDiscount(double percent)
{
    g_price = g_price - g_price * percent / 100.0;
}

solution.solution.cpp:
double applyDiscount(double price, double percent)
{
    return price - price * percent / 100.0;
}

unitTests:
TEST("fifteen percent off 200") { CHECK_NEAR(applyDiscount(200.0, 15.0), 170.0, 1e-9); }
TEST("no discount") { CHECK_NEAR(applyDiscount(80.0, 0.0), 80.0, 1e-9); }
TEST("everything off") { CHECK_NEAR(applyDiscount(80.0, 100.0), 0.0, 1e-9); }
TEST("calls do not affect each other") { applyDiscount(500.0, 50.0); CHECK_NEAR(applyDiscount(100.0, 10.0), 90.0, 1e-9); }

